package ktanesolver.module.modded.regular.equationsx;
import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;import ktanesolver.module.modded.regular.equationsx.EquationsXInput.Symbol;
class EquationsXSolverTest{@Test void mirrorsSourceRules(){BombEntity b=bomb();assertThat(solve(b,new EquationsXInput(Symbol.POWER,List.of(3,6))).answer()).isEqualTo(18);b.setStrikes(2);assertThat(solve(b,new EquationsXInput(Symbol.ANGULAR_ACCELERATION,List.of(2,8,4))).twitchCommand()).isEqualTo("nothing");b.setStrikes(0);assertThat(solve(b,new EquationsXInput(Symbol.KINETIC_ENERGY,List.of(2,3))).answer()).isEqualTo(9);}@SuppressWarnings("unchecked")static EquationsXOutput solve(BombEntity b,EquationsXInput i){ModuleEntity m=new ModuleEntity();m.setState(new HashMap<>());m.setSolution(new HashMap<>());return((SolveSuccess<EquationsXOutput>)new EquationsXSolver().solve(new RoundEntity(),b,m,i)).output();}static BombEntity bomb(){BombEntity b=new BombEntity();b.setSerialNumber("BCD246");b.setIndicators(new HashMap<>());b.setPortPlates(new ArrayList<>());b.setModules(new ArrayList<>());return b;}}
